// src/pages/Dashboard.js - Protected Dashboard Page
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getUserProfile } from '../api/authAPI';
import { useAuth } from '../context/AuthContext';

const Dashboard = () => {
  const navigate          = useNavigate();
  const { user, logout }  = useAuth();

  const [profile,  setProfile]  = useState(null);
  const [loading,  setLoading]  = useState(true);
  const [error,    setError]    = useState('');

  // ---- Fetch profile from backend on mount ----
  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const data = await getUserProfile();
        setProfile(data.user);
      } catch (err) {
        const msg = err.response?.data?.message || 'Session expired. Please log in again.';
        setError(msg);
        // If token is invalid/expired, log out and redirect
        if (err.response?.status === 401) {
          setTimeout(() => { logout(); navigate('/login'); }, 2000);
        }
      } finally {
        setLoading(false);
      }
    };
    fetchProfile();
  }, [logout, navigate]);

  // ---- Logout Handler ----
  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  // ---- Get initials for avatar ----
  const getInitials = (name) => {
    if (!name) return '?';
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  // ---- Format date ----
  const formatDate = (dateStr) => {
    if (!dateStr) return 'N/A';
    return new Date(dateStr).toLocaleDateString('en-US', {
      year: 'numeric', month: 'long', day: 'numeric',
    });
  };

  // ---- Loading state ----
  if (loading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Loading your dashboard...</p>
      </div>
    );
  }

  // Use profile from API or fallback to context user
  const displayUser = profile || user;

  return (
    <div className="dashboard-page">

      {/* ===================== NAVBAR ===================== */}
      <nav className="dashboard-nav">
        {/* Brand */}
        <div className="nav-brand">
          <div className="brand-dot">🔐</div>
          <span>AuthSystem</span>
        </div>

        {/* User info + logout */}
        <div className="nav-user">
          <div className="user-avatar">
            {getInitials(displayUser?.name)}
          </div>
          <span style={{ color: 'var(--text-muted)', fontSize: '0.875rem', display: 'none' }}>
            {displayUser?.name}
          </span>
          <button
            id="logout-btn"
            className="btn-logout"
            onClick={handleLogout}
          >
            <i className="bi bi-box-arrow-right"></i>
            Logout
          </button>
        </div>
      </nav>

      {/* ===================== MAIN CONTENT ===================== */}
      <main className="dashboard-main">

        {/* Error banner */}
        {error && (
          <div className="alert-custom alert-error mb-4">
            <i className="bi bi-exclamation-circle-fill"></i>
            {error}
          </div>
        )}

        {/* Welcome Banner */}
        <div className="welcome-banner">
          <div className="d-flex align-items-start justify-content-between flex-wrap gap-3">
            <div>
              <p style={{ color: 'var(--text-muted)', marginBottom: '0.4rem', fontSize: '0.9rem' }}>
                👋 Welcome back,
              </p>
              <h2>{displayUser?.name || 'User'}!</h2>
              <p>You are securely logged in to your account dashboard.</p>
            </div>
            <div className="status-badge">
              <div className="status-dot"></div>
              Session Active
            </div>
          </div>
        </div>

        {/* ---- Info Cards Grid ---- */}
        <div className="info-grid">

          {/* Name Card */}
          <div className="info-card">
            <div
              className="info-card-icon"
              style={{ background: 'rgba(79,70,229,0.15)', color: 'var(--primary-light)' }}
            >
              <i className="bi bi-person-fill"></i>
            </div>
            <div className="info-card-label">Full Name</div>
            <div className="info-card-value">{displayUser?.name || 'N/A'}</div>
          </div>

          {/* Email Card */}
          <div className="info-card">
            <div
              className="info-card-icon"
              style={{ background: 'rgba(6,182,212,0.15)', color: 'var(--secondary)' }}
            >
              <i className="bi bi-envelope-fill"></i>
            </div>
            <div className="info-card-label">Email Address</div>
            <div className="info-card-value">{displayUser?.email || 'N/A'}</div>
          </div>

          {/* Member Since Card */}
          <div className="info-card">
            <div
              className="info-card-icon"
              style={{ background: 'rgba(16,185,129,0.15)', color: '#6ee7b7' }}
            >
              <i className="bi bi-calendar-check-fill"></i>
            </div>
            <div className="info-card-label">Member Since</div>
            <div className="info-card-value">{formatDate(displayUser?.createdAt)}</div>
          </div>

          {/* User ID Card */}
          <div className="info-card">
            <div
              className="info-card-icon"
              style={{ background: 'rgba(245,158,11,0.15)', color: '#fcd34d' }}
            >
              <i className="bi bi-fingerprint"></i>
            </div>
            <div className="info-card-label">User ID</div>
            <div className="info-card-value" style={{ fontSize: '0.78rem' }}>
              {displayUser?.id || 'N/A'}
            </div>
          </div>
        </div>

        {/* ---- Security Features Notice ---- */}
        <div className="security-notice">
          <h5>
            <i className="bi bi-shield-check me-2"></i>
            Security Features Active
          </h5>

          <div className="security-item">
            <div className="si-icon"><i className="bi bi-check-lg"></i></div>
            <span>Password hashed with <strong style={{color:'var(--text-primary)'}}>bcrypt</strong> (salt rounds: 10) — never stored in plain text.</span>
          </div>

          <div className="security-item">
            <div className="si-icon"><i className="bi bi-check-lg"></i></div>
            <span><strong style={{color:'var(--text-primary)'}}>JWT Token</strong> authentication — stateless, secure, expires in 7 days.</span>
          </div>

          <div className="security-item">
            <div className="si-icon"><i className="bi bi-check-lg"></i></div>
            <span><strong style={{color:'var(--text-primary)'}}>Protected Routes</strong> — backend middleware validates token on every private request.</span>
          </div>

          <div className="security-item">
            <div className="si-icon"><i className="bi bi-check-lg"></i></div>
            <span><strong style={{color:'var(--text-primary)'}}>Password excluded</strong> from all API responses using Mongoose <code>.select('-password')</code>.</span>
          </div>

          <div className="security-item">
            <div className="si-icon"><i className="bi bi-check-lg"></i></div>
            <span><strong style={{color:'var(--text-primary)'}}>Unique email</strong> constraint enforced at both schema and controller level.</span>
          </div>
        </div>

      </main>
    </div>
  );
};

export default Dashboard;
